static double passAtK(int n, int c, int k) {
    if (n - c < k) {
        return 1.0;
    }
    double allFail = 1.0;
    for (int i = n - c + 1; i <= n; i++) {
        allFail *= 1.0 - (double) k / i;
    }
    return 1.0 - allFail;
}

static double cohenKappa(List<String> human, List<String> judge) {
    int n = human.size();
    int agree = 0;
    for (int i = 0; i < n; i++) {
        if (human.get(i).equals(judge.get(i))) agree++;
    }
    double po = (double) agree / n;
    double pe = 0.0;
    for (String label : new HashSet<>(human)) {
        pe += ((double) Collections.frequency(human, label) / n)
            * ((double) Collections.frequency(judge, label) / n);
    }
    return (po - pe) / (1 - pe);
}

